pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address depositor = address(0x1000);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        bool ok = true;
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
